175	/** Prüfziffer nach ISO 13616 (mod 97 = 1) und Länge je Land. Liefert { ok, iban, land, fehler } */
176	export function ibanPruefen(eingabe) {
177	  const iban = ibanNormalisieren(eingabe);
178	  if (!iban) return { ok: false, iban: "", land: "", fehler: "Bitte geben Sie eine IBAN an." };
179	  if (!/^[A-Z]{2}[0-9]{2}[A-Z0-9]{8,30}$/.test(iban)) return { ok: false, iban, land: iban.slice(0, 2), fehler: "Die IBAN hat ein ungültiges Format." };
180	  const land = iban.slice(0, 2);
181	  if (IBAN_LAENGE[land] && iban.length !== IBAN_LAENGE[land]) return { ok: false, iban, land, fehler: `Eine IBAN aus ${land} hat ${IBAN_LAENGE[land]} Zeichen.` };
182	  const umgestellt = iban.slice(4) + iban.slice(0, 4);
183	  let rest = 0;
184	  for (const ch of umgestellt) {
185	    const wert = ch >= "A" && ch <= "Z" ? String(ch.charCodeAt(0) - 55) : ch;
186	    for (const z of wert) rest = (rest * 10 + Number(z)) % 97;
187	  }
188	  if (rest !== 1) return { ok: false, iban, land, fehler: "Die Prüfziffer der IBAN stimmt nicht – bitte Eingabe prüfen." };
189	  return { ok: true, iban, land, fehler: "" };
190	}
