204	const RECHTSFORMEN = /\b(gmbh|ag|kg|og|ohg|gbr|ug|haftungsbeschrankt|mbh|co|eg|ev|se|sa|sarl|ltd|llc|inc|kgaa|stiftung|verein|genossenschaft|e\.?\s?u|eu)\b/g;
205	
206	export function nameNormalisieren(s) {
207	  return String(s || "")
208	    .toLowerCase()
209	    .replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss")
210	    .normalize("NFKD").replace(/[̀-ͯ]/g, "")
211	    .replace(/\(demo\)|\(fiktiv\)|\(test\)/g, " ")
212	    .replace(/[^a-z0-9 ]+/g, " ")
213	    .replace(/\s+/g, " ")
214	    .trim();
215	}
216	
217	export const nameTokens = (s, { firma = false } = {}) => {
218	  let n = nameNormalisieren(s);
219	  if (firma) n = n.replace(RECHTSFORMEN, " ").replace(/\s+/g, " ").trim();
220	  return n.split(" ").filter((t) => t.length > 1 && !["und", "the", "von", "van", "der", "de", "dr", "mag", "ing", "prof"].includes(t));
221	};
