223	/** Stimmt der Kontoinhaber mit der geprüften Person bzw. Firma überein? */
224	export function kontoinhaberPasst(inhaber, { vorname = "", nachname = "", firma = "" } = {}) {
225	  const t = new Set(nameTokens(inhaber, { firma: !!firma }));
226	  if (!t.size) return false;
227	  if (firma) {
228	    const f = nameTokens(firma, { firma: true });
229	    return f.length > 0 && f.every((x) => t.has(x));
230	  }
231	  const soll = [...nameTokens(vorname), ...nameTokens(nachname)];
232	  const nach = nameTokens(nachname);
233	  if (!nach.length) return false;
234	  // Nachname vollständig, Vorname mindestens der erste Vorname (oder Initiale)
235	  const vor = nameTokens(vorname);
236	  const vornameOk = !vor.length || t.has(vor[0]) || [...t].some((x) => x.length === 1 && x === vor[0][0]);
237	  return soll.length > 0 && nach.every((x) => t.has(x)) && vornameOk;
238	}
