242	export const heuteIso = (d = new Date()) => heuteLokal(d); // Europe/Vienna (Fristen: Ausweis, Wiederholungsprüfung, Löschung)
243	export function tageBis(datumIso, jetzt = new Date()) {
244	  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(datumIso || ""))) return null;
245	  return Math.floor((new Date(`${datumIso}T00:00:00Z`).getTime() - new Date(`${heuteIso(jetzt)}T00:00:00Z`).getTime()) / 86400000);
