247	export function monateSpaeter(datumIso, monate) {
248	  const d = new Date(`${String(datumIso).slice(0, 10)}T00:00:00Z`);
249	  if (Number.isNaN(d.getTime())) return null;
250	  d.setUTCMonth(d.getUTCMonth() + monate);
251	  return d.toISOString().slice(0, 10);
252	}
