288	/**
289	 * Anforderungen (Checkliste für Nutzer und Compliance). `kontext`:
290	 *   rollen[]      Rollen des Kontos (investor → Mittelherkunft; flaeche/landwirt → Eigentum + Auszahlung)
291	 *   flaechen[]    eigene Flächen [{ id, bezeichnung, land }]
292	 *   einstellungen KYC-Einstellungen
293	 * Liefert [{ id, gruppe, label, pflicht, erfuellt, hinweis, dokumentArt?, flaecheId?, personId? }]
294	 */
295	export function kycAnforderungen(fall, { rollen = [], flaechen = [], einstellungen = kycEinstellungenStandard() } = {}) {
296	  const f = fall || {};
297	  const docs = (f.dokumente || []).filter((d) => !d.geloescht && d.status !== "abgelehnt");
298	  const hat = (art, pred = () => true) => docs.some((d) => d.art === art && pred(d));
299	  const a = [];
300	  const add = (x) => a.push({ pflicht: true, ...x });
301	  const typ = f.kontotyp || "";
