385	/**
386	 * Risikoeinstufung nach Regeln (Land, PEP, Struktur, Ticketgröße, Sanktionstreffer).
387	 * Liefert { stufe: niedrig|mittel|hoch, punkte, gruende[] }. Compliance kann manuell höher/niedriger einstufen (mit Begründung).
388	 */
389	export function kycRisiko(fall, einstellungen = kycEinstellungenStandard()) {
390	  const f = fall || {};
391	  const hoch = new Set((einstellungen.hochrisikoLaender || []).map((x) => String(x).toUpperCase()));
392	  const gruende = [];
393	  let punkte = 0;
394	  const plus = (n, g) => {
395	    punkte += n;
396	    gruende.push(g);
397	  };
398	  const dach = ["DE", "AT", "CH", "LI"];
399	  const eu = ["BE", "BG", "CY", "CZ", "DK", "EE", "ES", "FI", "FR", "GR", "HR", "HU", "IE", "IT", "LT", "LU", "LV", "MT", "NL", "PL", "PT", "RO", "SE", "SI", "SK", "IS", "NO"];
400	  const laender = [f.person?.adresse?.land, f.person?.staatsangehoerigkeit, f.firma?.land, ...(f.ubos || []).map((u) => u.wohnsitzland)].filter(Boolean).map((x) => String(x).toUpperCase());
401	  if (laender.some((l) => hoch.has(l))) plus(4, "Bezug zu einem Drittland mit hohem Risiko");
402	  else if (laender.some((l) => !dach.includes(l) && !eu.includes(l))) plus(2, "Bezug außerhalb EU/EWR/Schweiz");
403	  else if (laender.some((l) => !dach.includes(l))) plus(1, "Bezug zu einem EU/EWR-Land außerhalb DACH");
404	  if (f.pep?.istPep) plus(4, "Politisch exponierte Person (verstärkte Sorgfaltspflichten)");
405	  else if (f.pep?.naheStehend) plus(4, "Familienangehöriger/nahestehende Person einer PEP");
406	  if ((f.ubos || []).some((u) => u.pep)) plus(4, "Wirtschaftlich Berechtigter ist PEP");
407	  if (f.kontotyp === "unternehmen") {
408	    const ubos = f.ubos || [];
409	    if (!ubos.length || ubos.every((u) => u.kontrolleArt === "fiktiv")) plus(2, "Kein wirtschaftlich Berechtigter über Anteile ermittelbar (fiktiver wB)");
410	    if (f.firma?.mehrstufig) plus(2, "Mehrstufige Beteiligungsstruktur");
411	    if (f.firma?.treuhand) plus(2, "Treuhand-/Stiftungsstruktur");
412	  }
413	  const betrag = KYC_TICKETS[f.mittelherkunft?.ticket]?.betrag || 0;
414	  if (betrag > 5000000) plus(2, "Ticketgröße über 5 Mio. €");
415	  else if (betrag > 1000000) plus(1, "Ticketgröße über 1 Mio. €");
416	  if (f.sanktionen?.status === "treffer_pruefen" || f.sanktionen?.status === "bestaetigt") plus(4, "Möglicher Treffer im Sanktionslisten-Abgleich");
417	  const stufe = punkte >= 4 ? "hoch" : punkte >= 2 ? "mittel" : "niedrig";
418	  return { stufe, punkte, gruende };
419	}
