425	/** Geltung der Freigabe-Sperren: Einstellung > Umgebung > Standard (Produktion „alle“, Entwicklung „pilot“) */
426	export function kycGeltung(einstellungen = {}, env = {}) {
427	  const e = einstellungen?.geltung;
428	  if (["alle", "pilot", "aus"].includes(e)) return e;
429	  const u = String(env.PLATTFORM_KYC_GATING || "").toLowerCase();
430	  if (["alle", "pilot", "aus"].includes(u)) return u;
431	  if (u === "an" || u === "1") return "alle";
432	  return env.NODE_ENV === "production" ? "alle" : "pilot";
433	}
