435	/** Ist der Schritt für dieses Konto gesperrt, solange es nicht verifiziert ist? */
436	export function kycSchrittAktiv(schritt, kontoId, einstellungen = kycEinstellungenStandard(), env = {}) {
437	  const e = { ...kycEinstellungenStandard(), ...(einstellungen || {}) };
438	  if (!KYC_SCHRITTE[schritt] || e.gating?.[schritt] === false) return false;
439	  const g = kycGeltung(e, env);
440	  if (g === "aus") return false;
441	  if (g === "pilot") return (e.pilotKonten || []).includes(kontoId);
442	  return true;
443	}
