445	/**
446	 * Freigabe-Entscheidung aus einem (bereits ermittelten) KYC-Status.
447	 * status: Ergebnis von kycStatus(); extra: { flaecheId } für Auszahlungen.
448	 */
449	export function kycFreigabe(schritt, status, { aktiv = true, flaecheId = null } = {}) {
450	  const def = KYC_SCHRITTE[schritt];
451	  if (!def) return { ok: false, aktiv: true, gruende: ["Unbekannter Schritt."], hinweis: "" };
452	  if (!aktiv) return { ok: true, aktiv: false, gruende: [], hinweis: "" };
453	  const gruende = [];
454	  if (!status?.verifiziert) gruende.push(status?.status === "abgelaufen" ? "Die Verifizierung muss erneuert werden." : "Die Verifizierung ist nicht abgeschlossen.");
455	  if (schritt === "auszahlung") {
456	    if (!status?.bank?.geprueft) gruende.push("Es fehlt eine geprüfte Bankverbindung (IBAN, Kontoinhaber = verifizierte Person/Firma).");
457	    if (flaecheId && !(status?.eigentum || []).includes(flaecheId)) gruende.push("Für diese Fläche liegt kein geprüfter Eigentumsnachweis vor.");
458	  }
459	  return { ok: gruende.length === 0, aktiv: true, gruende, hinweis: gruende.length ? def.hinweis : "" };
460	}
