19	/** Maßgeblicher Fall: eigener Fall des Kontos, sonst verifizierter KYB-Fall der Organisation */
20	export function kycFallFuer(db, { kontoId = null, organisationId = null } = {}) {
21	  const faelle = db?.kyc?.faelle || [];
22	  const eigen = kontoId ? faelle.find((f) => f.kontoId === kontoId && !f.organisationId) || faelle.find((f) => f.kontoId === kontoId) : null;
23	  const org = organisationId ? faelle.find((f) => f.organisationId === organisationId && f.status === "verifiziert") || faelle.find((f) => f.organisationId === organisationId) : null;
24	  if (eigen?.status === "verifiziert") return eigen;
25	  if (org?.status === "verifiziert") return org;
26	  return eigen || org || null;
27	}
