40	    verifiziert: f.status === "verifiziert",
41	    kontotyp: f.kontotyp || null,
42	    risiko: f.risiko?.stufe || null,
43	    bank: { vorhanden: !!f.bank?.iban, geprueft: f.status === "verifiziert" && !!f.bank?.geprueft },
44	    eigentum: f.status === "verifiziert" ? eigentum : [],
45	    verifiziertAm: f.verifiziertAm || null,
46	    naechstePruefung: f.naechstePruefung || null,
47	    ausweisGueltigBis: f.person?.ausweis?.gueltigBis || null,
