59	const ERGEBNIS_WERTE = ["ok", "auffaellig", "fehler", "hinweis", "ausstehend"];
60	const kurzText = (s, max) => String(s ?? "").replace(/[\u0000-\u001f]/g, " ").trim().slice(0, max);
61	
62	/**
63	 * Externes Prüfergebnis an einen KYC-Fall anhängen (Identitätsanbieter, MRZ-Vorprüfung, Registerabruf, Bonität …).
64	 * Nur innerhalb einer Schreib-Transaktion (db). Ergebnisse ENTSCHEIDEN NIE selbst – sie sind Hinweise für die Compliance.
65	 * eintrag: { quelle, art, ergebnis: ok|auffaellig|fehler|hinweis|ausstehend, zusammenfassung, rohdatenRef?, externeId?, daten? (flach, ≤ 30 Felder) }
66	 * fall: fallId oder { kontoId } / { organisationId }. Liefert den gespeicherten Eintrag.
67	 */
68	export function kycErgebnisAnhaengenDb(db, fall, eintrag = {}) {
69	  const faelle = db?.kyc?.faelle || [];
70	  const f = typeof fall === "string" ? faelle.find((x) => x.id === fall) : kycFallFuer(db, fall || {});
71	  if (!f) throw new PlattformFehler(404, "KYC-Fall nicht gefunden.");
72	  const quelle = kurzText(eintrag.quelle, 60);
73	  if (!quelle) throw new PlattformFehler(422, "Quelle des Prüfergebnisses fehlt.");
74	  const daten = {};
75	  for (const [k, w] of Object.entries(eintrag.daten && typeof eintrag.daten === "object" ? eintrag.daten : {}).slice(0, 30)) {
76	    const key = String(k).replace(/[^\w.-]/g, "").slice(0, 40);
77	    if (!key || ["__proto__", "constructor", "prototype"].includes(key)) continue;
78	    daten[key] = typeof w === "number" || typeof w === "boolean" ? w : kurzText(w, 300);
79	  }
80	  const e = {
81	    id: `KE-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`,
82	    quelle,
83	    art: kurzText(eintrag.art, 40) || "pruefung",
84	    ergebnis: ERGEBNIS_WERTE.includes(eintrag.ergebnis) ? eintrag.ergebnis : "hinweis",
85	    zusammenfassung: kurzText(eintrag.zusammenfassung, 500),
86	    rohdatenRef: kurzText(eintrag.rohdatenRef, 300) || null,
87	    externeId: kurzText(eintrag.externeId, 120) || null,
88	    daten,
89	    am: new Date().toISOString(),
90	  };
91	  f.pruefergebnisse = [...(f.pruefergebnisse || []), e].slice(-100);
92	  f.geaendertAm = e.am;
93	  return { fallId: f.id, ...e };
94	}
