98	 * werfen=true: 409 mit Hinweis; werfen=false: liefert false (Systemwechsel/Automation wird still übersprungen).
99	 */
100	export function kycUebergangPruefen(db, art, o, nach, { werfen = true } = {}) {
101	  let schritt = null;
102	  let ziel = null;
103	  if (art === "interesse" && nach === "nda_freigegeben") {
104	    schritt = "nda";
105	    ziel = { kontoId: o.investorId, organisationId: o.organisationId || null, text: "Datenraum-Freigabe nicht möglich: Der Investor ist noch nicht verifiziert (KYC/KYB)." };
106	  } else if (art === "interesse" && nach === "loi_abgegeben") {
107	    schritt = "loi";
108	    ziel = { kontoId: o.investorId, organisationId: o.organisationId || null };
109	  } else if (art === "projekt" && nach === "veroeffentlicht") {
110	    schritt = "veroeffentlichung";
111	    ziel = { kontoId: o.anbieterId, organisationId: o.organisationId || null, text: "Veröffentlichung nicht möglich: Der Anbieter ist noch nicht verifiziert (KYB)." };
112	  }
113	  if (!schritt) return true;
114	  if (werfen) {
115	    kycSperre(db, schritt, ziel);
116	    return true;
117	  }
118	  return kycFreigabeDb(db, schritt, ziel).ok;
119	}
120	
121	/** Wirft 409 (code „kyc“), wenn der Schritt für das Konto (noch) gesperrt ist */
122	export function kycSperre(db, schritt, ziel = {}) {
123	  const r = kycFreigabeDb(db, schritt, ziel);
124	  if (r.ok) return r;
125	  // ziel.text: eigener Hinweis (z. B. für das Backoffice „Der Investor ist noch nicht verifiziert“); sonst Hinweis für den Nutzer
126	  const text = ziel.text ? `${ziel.text} ${r.gruende.join(" ")}` : `${KYC_SCHRITTE[schritt]?.hinweis || "Bitte Verifizierung abschließen."} ${r.gruende.join(" ")} (Portal → Verifizierung)`;
127	  throw new PlattformFehler(409, text.trim(), "kyc");
128	}
