748	/**
749	 * Fristen-Lauf (täglich; Demo: manuell im Backoffice bzw. Test): Ausweis-Ablauf erinnern, Wiederholungsprüfung,
750	 * Sanktions-Neuabgleich bei neuem Listenstand, Löschung nach Aufbewahrungsfrist. `stichtag` nur für Tests/Vorschau.
751	 */
752	export async function kycFristen(n, { stichtag = null, fallId = null } = {}) {
753	  complianceNoetig(n);
754	  const zuLoeschen = [];
755	  const r = await aendernBereit((db) => {
756	    const e = kycEinstellungenDb(db);
757	    const heute = datum(stichtag) || heuteIso();
758	    const tage = (d) => (d ? Math.floor((new Date(`${d}T00:00:00Z`) - new Date(`${heute}T00:00:00Z`)) / 86400000) : null);
759	    const liste = sanktionsliste();
760	    const erg = { ausweisErinnert: 0, wiederholungErinnert: 0, abgelaufen: 0, neuAbgeglichen: 0, neueTreffer: 0, geloescht: 0 };
761	    for (const f of db.kyc.faelle) {
762	      if (f.status === "geloescht" || (fallId && f.id !== fallId)) continue;
763	      f.erinnerungen = f.erinnerungen || {};
764	      const gb = f.person?.ausweis?.gueltigBis;
765	      const t = tage(gb);
766	      if (f.status === "verifiziert" && t !== null && t <= (e.erinnerungAusweisTage || 30) && f.erinnerungen.ausweis !== gb) {
767	        f.erinnerungen.ausweis = gb;
768	        erg.ausweisErinnert++;
769	        nutzerMelden(db, f, t < 0 ? "Ausweis abgelaufen" : "Ausweis läuft bald ab", "Bitte aktualisieren Sie Ihre Ausweisdaten unter „Verifizierung“ (erneute Prüfung).");
770	        protokoll(db, n, "kyc_frist", "kyc", f.id, `Erinnerung Ausweis-Ablauf (${gb})`);
771	      }
772	      const w = tage(f.naechstePruefung);
773	      if (f.status === "verifiziert" && w !== null) {
774	        if (w <= 0) {
775	          f.status = "abgelaufen";
776	          verlauf(f, "abgelaufen", null, "system", "Wiederkehrende Überprüfung fällig.");
777	          erg.abgelaufen++;
778	          nutzerMelden(db, f, "Verifizierung erneuern", "Ihre regelmäßige Überprüfung ist fällig. Bitte bestätigen bzw. aktualisieren Sie Ihre Angaben.");
779	          protokoll(db, n, "kyc_frist", "kyc", f.id, "Wiederholungsprüfung fällig → abgelaufen");
780	        } else if (w <= 30 && f.erinnerungen.wiederholung !== f.naechstePruefung) {
781	          f.erinnerungen.wiederholung = f.naechstePruefung;
782	          erg.wiederholungErinnert++;
783	          nutzerMelden(db, f, "Überprüfung Ihrer Angaben steht an", "In den nächsten Wochen ist die regelmäßige Überprüfung fällig.");
784	        }
785	      }
786	      if (["verifiziert", "in_pruefung", "eingereicht", "zweitpruefung"].includes(f.status) && liste.stand && f.sanktionen?.listeStand !== liste.stand) {
787	        const vorher = new Set((f.sanktionen?.treffer || []).map((t) => `${t.eintragId}|${t.prueflingName}`));
788	        const s = abgleichAusfuehren(db, f, null, "Neuer Listenstand");
789	        erg.neuAbgeglichen++;
790	        // neuer, unbewerteter Treffer (auch wenn gleichzeitig ein alter wegfällt und die Anzahl gleich bleibt)
791	        if (s.status === "treffer_pruefen" && s.treffer.some((t) => !t.bewertung && !vorher.has(`${t.eintragId}|${t.prueflingName}`))) {
792	          erg.neueTreffer++;
793	          if (f.status === "verifiziert") {
794	            f.status = "in_pruefung";
795	            verlauf(f, "in_pruefung", null, "system", "Möglicher Treffer bei Neuabgleich.", { oeffentlich: false });
796	          }
797	          complianceMelden(db, f, `Sanktionsabgleich: möglicher Treffer ${f.id}`, "Manuelle Prüfung erforderlich.");
798	        }
799	      }
800	      if (f.loeschenAb && f.loeschenAb <= heute) {
801	        for (const d of db.kyc.dokumente.filter((x) => x.fallId === f.id && !x.geloescht)) {
802	          d.geloescht = true;
803	          d.geloeschtAm = jetzt();
804	          d.name = "(gelöscht)";
805	          zuLoeschen.push(d.datei);
806	        }
807	        const rest = { id: f.id, kontoId: null, organisationId: null, kontotyp: f.kontotyp, status: "geloescht", verlauf: [], geloeschtAm: jetzt(), loeschenAb: f.loeschenAb, erstelltAm: f.erstelltAm };
808	        for (const k of Object.keys(f)) delete f[k];
809	        Object.assign(f, rest);
810	        erg.geloescht++;
811	        protokoll(db, n, "kyc_loeschung", "kyc", f.id, "Aufbewahrungsfrist abgelaufen – Unterlagen und personenbezogene Angaben gelöscht");
812	      }
813	    }
814	    return { ok: true, stichtag: heute, ...erg };
815	  });
816	  for (const d of zuLoeschen) await dateiLoeschen(d);
817	  return r;
818	}
