24	async function kycHochladen(datei, felder) {
25	  const fd = new FormData();
26	  fd.append("datei", datei);
27	  for (const [k, w] of Object.entries(felder)) if (w) fd.append(k, w);
28	  const res = await fetch("/api/portal/kyc/dokumente", { method: "POST", body: fd, headers: { "X-Plattform-Upload": "1" }, credentials: "same-origin" });
29	  const json = await res.json().catch(() => ({}));
30	  if (!res.ok || json.ok === false) throw new Error(json.error || `Upload fehlgeschlagen (${res.status})`);
31	  return json.dokument;
32	}
