195	export async function terminBuchen(n, daten = {}, { ip = "" } = {}) {
196	  const art = v.auswahl(daten.art, TERMIN_ART_IDS, "");
197	  const a = artPruefen(n, art);
198	  const start = new Date(daten.start || "");
199	  v.pflicht(!Number.isNaN(start.getTime()), "Bitte wählen Sie einen Termin.");
200	  const bo = n && boSchreiben(n, BEREICH);
201	  if (!n) v.pflicht(v.wahr(daten.einwilligung), "Bitte stimmen Sie der Verarbeitung Ihrer Angaben zur Terminvereinbarung zu.");
202	  const kanal = a.kanal === "vor_ort" || !daten.kanal ? a.kanal : v.auswahl(daten.kanal, ["telefon", "video"], a.kanal);
203	  const notiz = v.mehrzeilig(daten.notiz, 1000);
204	  return aendernBereit((db) => {
205	    let kontoId = null;
206	    let kontakt;
207	    if (n && !bo) {
208	      const u = nutzerById(db, n.id);
209	      kontoId = u.id;
210	      kontakt = { name: nameVon(db, u.id), email: u.email, telefon: v.text(daten.telefon, 40) || u.telefon || "", firma: u.firma || "", plz: v.text(daten.kontakt?.plz, 10), ort: v.text(daten.kontakt?.ort, 80), land: v.auswahl(daten.kontakt?.land, ["DE", "AT", "CH"], "") };
211	    } else if (bo && daten.fuerKontoId) {
212	      const u = nutzerById(db, v.kennung(daten.fuerKontoId));
213	      if (!u) throw nichtGefunden("Konto nicht gefunden.");
214	      kontoId = u.id;
215	      kontakt = { name: nameVon(db, u.id), email: u.email, telefon: u.telefon || "", firma: u.firma || "" };
216	    } else kontakt = kontaktPruefen(daten.kontakt);
217	    // Missbrauchsschutz: höchstens 3 künftige aktive Termine je E-Mail-Adresse
218	    const offen = db.service.termine.filter((t) => t.kontakt?.email === kontakt.email && TERMIN_AKTIV.includes(t.status) && new Date(t.start) > new Date());
219	    if (!bo && offen.length >= 3) throw konflikt("Sie haben bereits drei offene Termine. Bitte sagen Sie einen ab oder melden Sie sich über das Portal.");
220	    const iso = start.toISOString();
221	    // Bezug (Vorgang/Fläche/Projekt): Kunden nur an eigene Objekte – sonst fremde Kennung im Backoffice-Termin
222	    let bezugArt = v.auswahl(daten.bezugArt, ["vorgang", "flaeche", "projekt"], "") || null;
223	    let bezugId = bezugArt ? v.kennung(daten.bezugId) || null : null;
224	    if (bezugArt && bezugId && !bo) {
225	      const o = ({ vorgang: db.vorgaenge, flaeche: db.flaechen, projekt: db.projekte }[bezugArt] || []).find((x) => x.id === bezugId);
226	      if (!o || !kontoId || (bezugArt === "projekt" ? o.anbieterId : o.nutzerId) !== kontoId) bezugArt = bezugId = null;
227	    }
228	    const mitarbeiterId = mitarbeiterWaehlen(db, art, iso, { wunschId: bo ? v.kennung(daten.mitarbeiterId) || null : null, ort: { land: kontakt.land, bundesland: v.text(daten.kontakt?.bundesland, 60), plz: kontakt.plz } });
229	    if (!mitarbeiterId) throw konflikt("Dieser Zeitpunkt ist nicht (mehr) frei. Bitte wählen Sie einen anderen Termin.");
230	    const t = {
231	      id: neueId("TE"), art, start: iso, ende: new Date(start.getTime() + a.dauer * 60e3).toISOString(), mitarbeiterId, vertretungFuerId: null, kontoId, kontakt,
232	      kanal, ort: a.kanal === "vor_ort" ? v.text(daten.ort || [kontakt.plz, kontakt.ort].filter(Boolean).join(" "), 160) : "", notiz,
