258	export async function termine(n, { alle = false, von = "", bis = "", mitarbeiterId = "", status = "" } = {}) {
259	  angemeldet(n);
260	  const bo = boLesen(n, BEREICH);
261	  if (alle && bo) {
262	    // Erinnerungen fällig? (Demo-Ersatz für den stündlichen Frappe-Job)
263	    await aendernBereit((db) => erinnerungenPruefen(db));
264	  }
265	  const db = await lesenBereit();
266	  const vonMs = tagGueltig(von) ? new Date(`${von}T00:00:00Z`).getTime() - 86400e3 : -Infinity;
267	  const bisMs = tagGueltig(bis) ? new Date(`${bis}T23:59:59Z`).getTime() + 86400e3 : Infinity;
268	  return db.service.termine
269	    .filter((t) => (alle && bo ? true : t.kontoId === n.id || t.mitarbeiterId === n.id))
270	    .filter((t) => !mitarbeiterId || t.mitarbeiterId === mitarbeiterId)
271	    .filter((t) => !status || t.status === status)
272	    .filter((t) => {
273	      const s = new Date(t.start).getTime();
274	      return s >= vonMs && s <= bisMs;
275	    })
276	    .sort((a, b) => a.start.localeCompare(b.start))
277	    .slice(0, 1000)
278	    .map((t) => ausgabe(db, n, t));
279	}
