294	function aktionAnwenden(db, n, t, { aktion, start, grund = "", mitarbeiterId }, { alsKunde }) {
295	  const a = TERMIN_ARTEN[t.art];
296	  const kommend = new Date(t.start).getTime() > Date.now();
297	  if (aktion === "stornieren") {
298	    if (!TERMIN_AKTIV.includes(t.status)) throw konflikt("Der Termin ist nicht mehr aktiv.");
299	    if (alsKunde && !kommend) throw konflikt("Vergangene Termine können nicht abgesagt werden.");
300	    t.status = "storniert";
301	    t.sequenz = (t.sequenz || 0) + 1;
302	    verlauf(t, `Abgesagt${grund ? `: ${v.text(grund, 200)}` : ""}`, n);
303	    icsVersenden(db, t, { anlass: "storniert" });
304	    melden(db, alsKunde ? t.mitarbeiterId : t.kontoId, { art: "termin", titel: `Termin abgesagt: ${a.label}`, text: zeitraumText(t.start, t.ende), link: alsKunde ? "/portal/admin/kalender" : "/portal/termine", objektArt: "termin", objektId: t.id }, { mail: false });
305	    return;
306	  }
307	  if (aktion === "umbuchen") {
308	    if (!TERMIN_AKTIV.includes(t.status) || !kommend) throw konflikt("Nur künftige, aktive Termine können verschoben werden.");
309	    const neu = new Date(start || "");
310	    v.pflicht(!Number.isNaN(neu.getTime()), "Bitte wählen Sie einen neuen Termin.");
311	    const iso = neu.toISOString();
312	    // gleiche Person bevorzugt, sonst eine andere mit freiem Slot
313	    let ziel = slotFrei(iso, slotParameter(db, t.mitarbeiterId, t.art, { ohneId: t.id })) ? t.mitarbeiterId : null;
314	    if (!ziel) ziel = mitarbeiterWaehlen(db, t.art, iso);
315	    if (!ziel) throw konflikt("Dieser Zeitpunkt ist nicht (mehr) frei. Bitte wählen Sie einen anderen Termin.");
316	    const alt = zeitraumText(t.start, t.ende);
317	    t.start = iso;
318	    t.ende = new Date(neu.getTime() + a.dauer * 60e3).toISOString();
319	    t.mitarbeiterId = ziel;
320	    t.status = "gebucht";
321	    t.erinnertAm = null;
322	    t.sequenz = (t.sequenz || 0) + 1;
323	    verlauf(t, `Verschoben von ${alt} auf ${zeitraumText(t.start, t.ende)}`, n);
324	    icsVersenden(db, t, { anlass: "umgebucht" });
325	    melden(db, alsKunde ? t.mitarbeiterId : t.kontoId, { art: "termin", titel: `Termin verschoben: ${a.label}`, text: zeitraumText(t.start, t.ende), link: alsKunde ? "/portal/admin/kalender" : "/portal/termine", objektArt: "termin", objektId: t.id }, { mail: false });
326	    return;
327	  }
328	  if (alsKunde) throw verboten("Diese Änderung kann nur das Backoffice vornehmen.");
329	  if (aktion === "bestaetigen") {
330	    if (t.status !== "gebucht") throw konflikt("Nur gebuchte Termine können bestätigt werden.");
331	    t.status = "bestaetigt";
332	    verlauf(t, "Bestätigt", n);
333	    icsVersenden(db, t, { anlass: "bestaetigt" });
334	    return;
335	  }
336	  if (aktion === "erledigt" || aktion === "nicht_erschienen") {
337	    if (!TERMIN_AKTIV.includes(t.status)) throw konflikt("Der Termin ist nicht mehr aktiv.");
338	    t.status = aktion;
339	    verlauf(t, TERMIN_STATUS[aktion].label, n);
340	    return;
341	  }
342	  if (aktion === "zuweisen") {
343	    const z = nutzerById(db, v.kennung(mitarbeiterId));
344	    v.pflicht(z && z.aktiv && z.rollen.includes("admin"), "Zuständig kann nur ein aktives Backoffice-Konto sein.");
345	    if (!slotFrei(t.start, { ...slotParameter(db, z.id, t.art, { ohneId: t.id }), vorlaufStunden: 0 })) throw konflikt(`${nameVon(db, z.id)} ist zu diesem Zeitpunkt nicht verfügbar.`);
346	    t.mitarbeiterId = z.id;
347	    t.sequenz = (t.sequenz || 0) + 1;
348	    verlauf(t, `Zugewiesen an ${nameVon(db, z.id)}`, n);
349	    icsVersenden(db, t, { anlass: "vertretung" });
350	    melden(db, z.id, { art: "termin", titel: `Termin übernommen: ${a.label}`, text: zeitraumText(t.start, t.ende), link: "/portal/admin/kalender", objektArt: "termin", objektId: t.id }, { mail: false });
351	    return;
352	  }
353	  throw new PlattformFehler(422, "Unbekannte Aktion.");
354	}
