	"""Wirft KycErforderlich (ValidationError, HTTP 409) mit Hinweis, wenn der Schritt gesperrt ist."""
	import frappe

	r = kyc_freigabe(schritt, konto_id, organisation_id, flaeche_id)
	if r["ok"]:
