// scripts/plattform-test-kyc.mjs
//
// End-to-End-Test „KYC/KYB – Identitäts- und Firmenprüfung“ gegen den laufenden Dev-Server (Demo-Backend).
//   node scripts/plattform-test-kyc.mjs [basis-url]
