      namen: Object.fromEntries([p.durchfuehrenderId, ...(p.eintraege || []).map((x) => x.vonId)].filter(Boolean).map((id) => [id, nameVon(db, id) || id])),
      erstelltVon: nameVon(db, n.id) || n.id,
