// GET  /api/portal/dienste/eid – verfügbare eID-Verfahren (ID Austria, Online-Ausweis; ggf. DEMO), eigene Vorgänge, Nachweis
// POST /api/portal/dienste/eid – { methode: id_austria | online_ausweis } → { vorgang, url } (Weiterleitung zum Aussteller)
//      Setzt die Browser-Bindung des Vorgangs als HttpOnly-Cookie (nur für den Rücksprung-Pfad, 15 min) – nie im Body/URL.
import { antwort, basisUrl, route } from "@/lib/plattform/server/route";
import { eidBackend } from "@/lib/plattform/backend/eid";
import { EID_BINDUNG_COOKIE, EID_REDIRECT_PFAD } from "@/lib/plattform/dienste/eid/methoden";

export const GET = route({}, async ({ nutzer }) => ({ ok: true, ...(await eidBackend().eidStatus(nutzer)) }));

export const POST = route({}, async ({ nutzer, request, body }) => {
  const { bindung, ...rest } = await eidBackend().eidStarten(nutzer, { methode: body.methode, basisUrl: basisUrl(request) });
  const res = antwort({ ok: true, ...rest });
  res.cookies.set(EID_BINDUNG_COOKIE, bindung, { httpOnly: true, sameSite: "lax", secure: process.env.NODE_ENV === "production", path: EID_REDIRECT_PFAD, maxAge: 15 * 60 });
  return res;
});
| Was | Wo |
| --- | --- |
| Weg in `KYC_METHODEN` | Eintrag `eid`: `verfuegbar: true`, `varianten: ["id_austria","online_ausweis"]`, `start: "/api/portal/dienste/eid"` |
| Tatsächlich startbare Varianten | `GET /api/portal/dienste/eid` → `methoden: [{ id, label, land, kurz, text, icon, demo, aktiv, loaMin }]` (leer = eID derzeit nicht anbieten). Serverseitig: `eidVerfuegbar()` aus `src/lib/plattform/dienste/eid/methoden.js` (nur Server, nutzt node:crypto) |
| Start-Schaltflächen (fertig) | `@/components/Portal/Dienste/EidStart` – Props `{ methoden }`; startet und leitet weiter |
| Start per API | `POST /api/portal/dienste/eid` `{ methode }` → `{ vorgang: { id, methode, demo }, url }`; Browser mit `window.location.assign(url)` weiterleiten |
| Rückkehr ins Portal | `/portal/verifizierung?eid=<EI-…>&ergebnis=bestanden|abgelehnt|fehler|abgebrochen` bzw. `?eid=ungueltig|doppelt|limit|fehler|anmeldung` (nie Code/Token in der URL) |
| Nachweis/Status des Nutzers | `GET /api/portal/dienste/eid` → `nachweis` (jüngster gültiger: `{ methode, demo, vorname, nachname, geburtsdatum, vertrauensniveau, am, transaktionsId, identitaetBestaetigt, abgleich }`), `vorgaenge` (letzte 5), `regel.hochBestaetigt` |
| Im KYC-Fall | `pruefergebnisse[]` mit `art: "eid"`, `quelle: "eID ID Austria" | "eID Online-Ausweis"` (+ „ (DEMO)“), `ergebnis: ok | auffaellig | hinweis | fehler`, `daten: { vorgang, methode, vertrauensniveau, zeitpunkt, transaktionsId, nameStimmt, geburtsdatumStimmt, dublette, identitaetBestaetigt, regelHochBestaetigt, demo }` |
| Backend-intern (Demo) | `eidNachweisDb(db, kontoId)` bzw. `await eidNachweis(kontoId)` aus `backend/demo/eid.js` |
| Backend-intern (Frappe) | `oekoinvest_app.plattform.api.eid.eid_nachweis(konto_id)` |

Hinweise für Team 1:
- `kycIdentNachweis(f, "eid")` erkennt die Hinweise bereits (Regex auf `art/quelle`, `ergebnis: "ok"`). Bitte zusätzlich `daten.demo === true` im Echtbetrieb nicht als Nachweis werten und für „Identität bestätigt“ `daten.identitaetBestaetigt` verwenden (nicht nur `ergebnis: "ok"`).
- Python: `kyc_ident_kern.py` führt `eid` noch mit `"verfuegbar": False` (Team-1-Datei, nicht geändert). Vorschlag: dort `verfuegbar` aus `oekoinvest_app.plattform.eid_kern.verfuegbar(frappe.conf.get, demo_erlaubt=…)` ableiten.

## Operationen (Backend `eidBackend()` – Demo und Frappe gleich)

| Operation | Frappe-Methode | Rechte |
| --- | --- | --- |
| `eidStatus(n)` | `eid.eid_status` | Person selbst |

DT = "Plattform eID Vorgang"
TIMEOUT = 15
EINSTELLUNG_REGEL = "oekoinvest_eid_hoch_bestaetigt"


def _conf(k):
	return frappe.conf.get(k)


def _demo_erlaubt():
	return bool(frappe.conf.get("developer_mode") or cint(frappe.conf.get("oekoinvest_dienste_demo")) or cint(frappe.conf.get("oekoinvest_eid_demo")))


def _konfig(methode):
	return ek.konfig(methode, _conf, demo_erlaubt=_demo_erlaubt(), produktion=not frappe.conf.get("developer_mode"))


def _regel():
	return bool(cint(frappe.db.get_default(EINSTELLUNG_REGEL) or 0))

}

/**
 * Für den KYC-Assistenten (Team „Eigene Identifizierung“): verfügbare eID-Methoden.
 * Liefert [{ id, label, land, kurz, text, demo, aktiv, loaMin }] – nur Methoden, die gestartet werden können.
 */
export function eidVerfuegbar(env = process.env) {
  return EID_METHODEN_IDS.map((id) => ({ m: EID_METHODEN[id], k: eidKonfig(id, env) }))
    .filter(({ k }) => k?.aktiv)
    .map(({ m, k }) => ({ id: m.id, label: m.label, land: m.land, kurz: m.kurz, text: m.text, icon: m.icon, demo: k.demo, aktiv: true, loaMin: k.loaMin }));
}

/** Einträge für KYC_METHODEN (kyc.js, Team 1) – gleiche Form, eID-Teil */
export const EID_KYC_METHODEN = Object.fromEntries(EID_METHODEN_IDS.map((id) => [`eid_${id}`, {
  label: EID_METHODEN[id].label, land: EID_METHODEN[id].land, art: "eid", eidMethode: id, kurz: EID_METHODEN[id].kurz, start: "/api/portal/dienste/eid",
}]));
