// Team „Eigene Identifizierung“ – node ident_shot.mjs <breite> [fallId-Compliance] – ein Browser, immer schließen
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";

const B = "http://localhost:3100";
const breite = Number(process.argv[2]) || 390;
const fallId = process.argv[3] || "";
const H = { Origin: B };
const pfad = (n) => fileURLToPath(new URL(`./shots/ident_${n}_${breite}.png`, import.meta.url));
const pz = (s) => [...s].reduce((a, c, i) => a + (c === "<" ? 0 : /\d/.test(c) ? Number(c) : c.charCodeAt(0) - 55) * [7, 3, 1][i % 3], 0) % 10;

const b = await chromium.launch();
try {
  const ctx = await b.newContext({ viewport: { width: breite, height: breite < 600 ? 844 : 900 }, deviceScaleFactor: 1 });
  const lauf = Date.now().toString(36);
  const email = `kyc-test-shot${lauf}@example.com`;
  let r = await ctx.request.post(`${B}/api/auth/registrieren`, { data: { email, passwort: "Kyc-Test-Passwort-2026", vorname: "Erika", nachname: "Beispiel", rollen: ["investor"], agb: true }, headers: H, timeout: 180000 });
  console.log("registrieren", r.status());
  await ctx.request.patch(`${B}/api/portal/kyc`, { data: { abschnitt: "kontotyp", daten: { kontotyp: "privat" } }, headers: H, timeout: 180000 });
  await ctx.request.patch(`${B}/api/portal/kyc`, { data: { abschnitt: "person", daten: { vorname: "Erika", nachname: "Beispiel", geburtsdatum: "1980-02-03", geburtsort: "Teststadt", staatsangehoerigkeit: "DE", adresse: { strasse: "Testweg 1", plz: "86842", ort: "Teststadt", land: "DE" }, ausweis: { art: "personalausweis", nummer: "T22000129", behoerde: "Stadt Teststadt", gueltigBis: "2031-01-01" } } }, headers: H, timeout: 180000 });
  const p = await ctx.newPage();
  const fehler = [];
  p.on("pageerror", (e) => fehler.push(`PAGEERROR ${e.message}`));
  p.on("console", (m) => m.type() === "error" && fehler.push(`CONSOLE ${m.text().slice(0, 200)}`));
  r = await p.goto(`${B}/portal/verifizierung`, { waitUntil: "load", timeout: 180000 });
  await p.waitForTimeout(3000);
  await p.getByRole("button", { name: /Identifizierung/ }).first().click();
  await p.waitForTimeout(1500);
  await p.getByRole("radio", { name: /Videogespräch mit ÖkoInvest/ }).click();
  await p.waitForTimeout(4000);
  await p.getByRole("button", { name: "Wo steht die MRZ?" }).click();
  const nr = "T22000129";
  const a = `IDD<<${nr}${pz(nr)}`.padEnd(30, "<");
  const b0 = `800203${pz("800203")}F310101${pz("310101")}D<<`.padEnd(29, "<");
  const zeilen = [a, b0 + pz(a.slice(5, 30) + b0.slice(0, 7) + b0.slice(8, 15) + b0.slice(18, 29)), "BEISPIEL<<ERIKA".padEnd(30, "<")];
  for (let i = 0; i < 3; i++) await p.getByLabel(`MRZ Zeile ${i + 1} von 3, 30 Zeichen`).fill(zeilen[i]);
  await p.waitForTimeout(1500);
  const ueber = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  await p.screenshot({ path: pfad("ausweis"), fullPage: true });
  console.log(r.status(), "verifizierung/ausweis", "Überlauf", ueber, fehler.join("\n"));
  if (fallId) {
    const c = await b.newContext({ viewport: { width: breite, height: 900 }, deviceScaleFactor: 1 });
    await c.request.post(`${B}/api/auth/login`, { data: { email: "bo-compliance@example.com", passwort: "Demo-2026!" }, headers: H, timeout: 180000 });
    const q = await c.newPage();
    const f2 = [];
    q.on("pageerror", (e) => f2.push(`PAGEERROR ${e.message}`));
    r = await q.goto(`${B}/portal/admin/compliance/${fallId}`, { waitUntil: "load", timeout: 180000 });
    await q.waitForTimeout(4000);
    const u2 = await q.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    await q.screenshot({ path: pfad("compliance"), fullPage: true });
    console.log(r.status(), "compliance", "Überlauf", u2, f2.join("\n"));
  }
} finally {
  await b.close();
}

